-- PROPOSED ONLY. Depends on proposed 009 and 010. Never run by the approved eight-migration workflow.
-- Additive financial records, immutable invoices and adjustments. No existing data/roles/grants rewritten.
INSERT INTO ab.permissions(id) SELECT 'vehicle_'||unnest(ARRAY['view','create','edit','funding_approve','disburse','receive_funds','settle_custody','invoices','collect','approve','reschedule','reschedule_extend','sale','sale_approve','print','export','insurance','gps','location','keys','circular_issue','circular_complete','circular_exception','recovery','recovery_approve','recovery_assign','recovery_close','settlement','writeoff_approve','configure','documents','notify','audit','import']) ON CONFLICT DO NOTHING;
CREATE TABLE ab.vehicle_numbers(tenant_id uuid NOT NULL REFERENCES ab.organizations,kind text NOT NULL,next_number bigint NOT NULL CHECK(next_number>0),PRIMARY KEY(tenant_id,kind));
CREATE TABLE ab.vehicle_requests(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,company_id uuid NOT NULL,customer_id uuid NOT NULL,request_number bigint NOT NULL,finance_type text NOT NULL CHECK(finance_type IN('group','investor','cash','bank')),funding_state text NOT NULL CHECK(funding_state IN('NotRequired','Requested','Approved','Rejected')),payload_cipher text NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),revision integer NOT NULL DEFAULT 1,UNIQUE(tenant_id,id),UNIQUE(tenant_id,request_number),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,customer_id)REFERENCES ab.customers(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.vehicle_assets(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,vin_digest text NOT NULL,UNIQUE(tenant_id,id),UNIQUE(tenant_id,vin_digest));
CREATE TABLE ab.vehicles(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,company_id uuid NOT NULL,customer_id uuid NOT NULL,request_id uuid NOT NULL,asset_id uuid,file_number bigint NOT NULL,status text NOT NULL CHECK(status IN('Active','Pending','Terminated')),payload_cipher text NOT NULL,search_tokens text[] NOT NULL DEFAULT '{}',revision integer NOT NULL DEFAULT 1,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,company_id,id),UNIQUE(tenant_id,file_number),UNIQUE(tenant_id,request_id),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,customer_id)REFERENCES ab.customers(tenant_id,id),FOREIGN KEY(tenant_id,request_id)REFERENCES ab.vehicle_requests(tenant_id,id),FOREIGN KEY(tenant_id,asset_id)REFERENCES ab.vehicle_assets(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE INDEX vehicle_list ON ab.vehicles(tenant_id,company_id,file_number);
CREATE INDEX vehicle_search ON ab.vehicles USING gin(search_tokens);
CREATE TABLE ab.vehicle_events(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,company_id uuid NOT NULL,vehicle_id uuid,request_id uuid,actor_id uuid,actor_type text NOT NULL DEFAULT 'user' CHECK(actor_type IN('user','service')),kind text NOT NULL,source_key text,payload_cipher text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,vehicle_id)REFERENCES ab.vehicles(tenant_id,id),FOREIGN KEY(tenant_id,request_id)REFERENCES ab.vehicle_requests(tenant_id,id),FOREIGN KEY(tenant_id,actor_id)REFERENCES ab.users(tenant_id,id));
CREATE UNIQUE INDEX vehicle_event_source ON ab.vehicle_events(tenant_id,vehicle_id,source_key) WHERE source_key IS NOT NULL;
CREATE INDEX vehicle_history ON ab.vehicle_events(tenant_id,vehicle_id,created_at);
CREATE TABLE ab.vehicle_funds(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,company_id uuid NOT NULL,request_id uuid NOT NULL,receiver_id uuid NOT NULL,amount numeric(21,3) NOT NULL CHECK(amount>0),currency char(3) NOT NULL,method text NOT NULL CHECK(method IN('cash','cheque','transfer')),state text NOT NULL CHECK(state IN('AwaitingReceipt','Held','Settled')),payment_operation_id uuid,payload_cipher text NOT NULL,created_by uuid NOT NULL,received_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,request_id),UNIQUE(tenant_id,payment_operation_id),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,request_id)REFERENCES ab.vehicle_requests(tenant_id,id),FOREIGN KEY(tenant_id,receiver_id)REFERENCES ab.users(tenant_id,id),FOREIGN KEY(tenant_id,payment_operation_id)REFERENCES ab.finance_operations(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.vehicle_contracts(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,company_id uuid NOT NULL,vehicle_id uuid NOT NULL,payload_cipher text NOT NULL,created_by uuid,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,company_id,vehicle_id)REFERENCES ab.vehicles(tenant_id,company_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.vehicle_invoices(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,company_id uuid NOT NULL,customer_id uuid NOT NULL,vehicle_id uuid NOT NULL,invoice_number bigint NOT NULL,kind text NOT NULL CHECK(kind IN('finance','service','insurance','gps','salik','fine','admin','circular','recovery')),source_key text NOT NULL,contract_id uuid,due_on date NOT NULL,amount numeric(21,3) NOT NULL CHECK(amount>0),currency char(3) NOT NULL,payload_cipher text NOT NULL,created_by uuid,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,company_id,id),UNIQUE(tenant_id,invoice_number),UNIQUE(tenant_id,vehicle_id,source_key),FOREIGN KEY(tenant_id,company_id,vehicle_id)REFERENCES ab.vehicles(tenant_id,company_id,id),FOREIGN KEY(tenant_id,customer_id)REFERENCES ab.customers(tenant_id,id),FOREIGN KEY(tenant_id,contract_id)REFERENCES ab.vehicle_contracts(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE INDEX vehicle_due ON ab.vehicle_invoices(tenant_id,company_id,customer_id,due_on);
CREATE TABLE ab.vehicle_allocations(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,company_id uuid NOT NULL,invoice_id uuid NOT NULL,operation_id uuid NOT NULL,amount numeric(21,3) NOT NULL CHECK(amount>0),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,invoice_id,operation_id),FOREIGN KEY(tenant_id,company_id,invoice_id)REFERENCES ab.vehicle_invoices(tenant_id,company_id,id),FOREIGN KEY(tenant_id,operation_id)REFERENCES ab.finance_operations(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.vehicle_actions(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,company_id uuid NOT NULL,vehicle_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('sale','waiver','writeoff','reschedule_extension','wanted','settlement')),state text NOT NULL CHECK(state IN('Requested','Approved','Conditional','Returned','Rejected','Executed')),payload_cipher text NOT NULL,decision_cipher text,created_by uuid NOT NULL,decided_by uuid,created_at timestamptz NOT NULL DEFAULT now(),decided_at timestamptz,UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,company_id,vehicle_id)REFERENCES ab.vehicles(tenant_id,company_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id),FOREIGN KEY(tenant_id,decided_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.vehicle_invoice_adjustments(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,company_id uuid NOT NULL,invoice_id uuid NOT NULL,action_id uuid,kind text NOT NULL CHECK(kind IN('waiver','writeoff','reschedule','termination')),amount numeric(21,3) NOT NULL CHECK(amount>0),payload_cipher text NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,company_id,invoice_id)REFERENCES ab.vehicle_invoices(tenant_id,company_id,id),FOREIGN KEY(tenant_id,action_id)REFERENCES ab.vehicle_actions(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.vehicle_expenses(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,company_id uuid NOT NULL,vehicle_id uuid NOT NULL,invoice_id uuid,kind text NOT NULL CHECK(kind IN('insurance','gps','recovery')),cost numeric(21,3) NOT NULL CHECK(cost>=0),currency char(3) NOT NULL,payload_cipher text NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,company_id,vehicle_id)REFERENCES ab.vehicles(tenant_id,company_id,id),FOREIGN KEY(tenant_id,invoice_id)REFERENCES ab.vehicle_invoices(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.vehicle_circulars(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,company_id uuid NOT NULL,payload_cipher text NOT NULL,effective_on date NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.vehicle_circular_results(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,company_id uuid NOT NULL,vehicle_id uuid NOT NULL,circular_id uuid NOT NULL,state text NOT NULL CHECK(state IN('InProgress','Completed','Exempted')),payload_cipher text NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,company_id,vehicle_id)REFERENCES ab.vehicles(tenant_id,company_id,id),FOREIGN KEY(tenant_id,circular_id)REFERENCES ab.vehicle_circulars(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.vehicle_recovery_tasks(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,company_id uuid NOT NULL,vehicle_id uuid NOT NULL,action_id uuid NOT NULL,assignee_id uuid NOT NULL,state text NOT NULL CHECK(state IN('Open','Closed')),due_at timestamptz NOT NULL,payload_cipher text NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,action_id),FOREIGN KEY(tenant_id,company_id,vehicle_id)REFERENCES ab.vehicles(tenant_id,company_id,id),FOREIGN KEY(tenant_id,action_id)REFERENCES ab.vehicle_actions(tenant_id,id),FOREIGN KEY(tenant_id,assignee_id)REFERENCES ab.users(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.vehicle_files(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,company_id uuid NOT NULL,vehicle_id uuid NOT NULL,parent_id uuid,version integer NOT NULL CHECK(version>0),storage_key text NOT NULL UNIQUE,digest text NOT NULL,mime text NOT NULL CHECK(mime IN('application/pdf','image/png','image/jpeg','image/webp')),size integer NOT NULL CHECK(size BETWEEN 1 AND 10485760),scan_status text NOT NULL CHECK(scan_status IN('pending','clean','rejected')),payload_cipher text NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,parent_id),FOREIGN KEY(tenant_id,company_id,vehicle_id)REFERENCES ab.vehicles(tenant_id,company_id,id),FOREIGN KEY(tenant_id,parent_id)REFERENCES ab.vehicle_files(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.vehicle_file_reviews(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,file_id uuid NOT NULL,verdict text NOT NULL CHECK(verdict IN('clean','rejected')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,file_id),FOREIGN KEY(tenant_id,file_id)REFERENCES ab.vehicle_files(tenant_id,id));
CREATE TABLE ab.vehicle_billing_jobs(tenant_id uuid NOT NULL,company_id uuid NOT NULL,enabled boolean NOT NULL DEFAULT false,PRIMARY KEY(tenant_id,company_id),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id));
DO $$ DECLARE tab text; BEGIN FOREACH tab IN ARRAY ARRAY['vehicle_numbers','vehicle_requests','vehicle_assets','vehicles','vehicle_events','vehicle_funds','vehicle_contracts','vehicle_invoices','vehicle_allocations','vehicle_actions','vehicle_invoice_adjustments','vehicle_expenses','vehicle_circulars','vehicle_circular_results','vehicle_recovery_tasks','vehicle_files','vehicle_file_reviews','vehicle_billing_jobs'] LOOP
 EXECUTE format('ALTER TABLE ab.%I ENABLE ROW LEVEL SECURITY',tab);EXECUTE format('CREATE POLICY tenant_scope ON ab.%I USING(tenant_id=ab.tenant()) WITH CHECK(tenant_id=ab.tenant())',tab);EXECUTE format('GRANT SELECT,INSERT ON ab.%I TO ab_runtime',tab);
 END LOOP; END $$;
REVOKE INSERT ON ab.vehicle_file_reviews FROM ab_runtime;
GRANT UPDATE ON ab.vehicle_numbers,ab.vehicle_requests,ab.vehicles,ab.vehicle_funds,ab.vehicle_actions,ab.vehicle_recovery_tasks,ab.vehicle_billing_jobs TO ab_runtime;
CREATE FUNCTION ab.vehicle_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable vehicle history' USING ERRCODE='23514'; END $$;
DO $$ DECLARE tab text; BEGIN FOREACH tab IN ARRAY ARRAY['vehicle_events','vehicle_contracts','vehicle_invoices','vehicle_allocations','vehicle_invoice_adjustments','vehicle_expenses','vehicle_circulars','vehicle_circular_results','vehicle_files','vehicle_file_reviews'] LOOP EXECUTE format('CREATE TRIGGER history_immutable BEFORE UPDATE OR DELETE ON ab.%I FOR EACH ROW EXECUTE FUNCTION ab.vehicle_immutable()',tab); END LOOP; END $$;
CREATE FUNCTION ab.vehicle_allocation_valid() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE bill ab.vehicle_invoices;op ab.finance_operations; BEGIN SELECT * INTO bill FROM ab.vehicle_invoices WHERE tenant_id=NEW.tenant_id AND id=NEW.invoice_id;SELECT * INTO op FROM ab.finance_operations WHERE tenant_id=NEW.tenant_id AND id=NEW.operation_id;IF op.status IS DISTINCT FROM 'Approved' OR op.kind IS DISTINCT FROM 'receipt' OR op.company_id IS DISTINCT FROM bill.company_id OR op.currency IS DISTINCT FROM bill.currency OR (op.integration_refs->>'clientReference') IS DISTINCT FROM bill.customer_id::text OR (op.integration_refs->>'vehicleReference') IS DISTINCT FROM bill.vehicle_id::text THEN RAISE EXCEPTION 'invalid receipt allocation' USING ERRCODE='23514';END IF;IF (SELECT coalesce(sum(amount),0) FROM ab.vehicle_allocations WHERE tenant_id=NEW.tenant_id AND operation_id=NEW.operation_id)>op.amount OR (SELECT coalesce(sum(amount),0)FROM ab.vehicle_allocations WHERE tenant_id=NEW.tenant_id AND invoice_id=bill.id)+(SELECT coalesce(sum(amount),0)FROM ab.vehicle_invoice_adjustments WHERE tenant_id=NEW.tenant_id AND invoice_id=bill.id AND kind<>'writeoff')>bill.amount THEN RAISE EXCEPTION 'allocation exceeds funds or invoice' USING ERRCODE='23514';END IF;RETURN NULL;END $$;
CREATE CONSTRAINT TRIGGER allocation_balance AFTER INSERT ON ab.vehicle_allocations DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ab.vehicle_allocation_valid();
CREATE FUNCTION ab.vehicle_credit_valid() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF (SELECT coalesce(sum(amount),0)FROM ab.vehicle_allocations WHERE tenant_id=NEW.tenant_id AND invoice_id=NEW.invoice_id)+(SELECT coalesce(sum(amount),0)FROM ab.vehicle_invoice_adjustments WHERE tenant_id=NEW.tenant_id AND invoice_id=NEW.invoice_id AND (kind<>'writeoff' OR NEW.kind='writeoff'))>(SELECT amount FROM ab.vehicle_invoices WHERE tenant_id=NEW.tenant_id AND id=NEW.invoice_id)THEN RAISE EXCEPTION 'credit exceeds invoice' USING ERRCODE='23514';END IF;RETURN NULL;END $$;
CREATE CONSTRAINT TRIGGER invoice_credit_balance AFTER INSERT ON ab.vehicle_invoice_adjustments DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ab.vehicle_credit_valid();
CREATE FUNCTION ab.pending_vehicle_files() RETURNS TABLE(id uuid,storage_key text,mime text,sha256 text) LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,ab AS $$ SELECT f.id,f.storage_key,f.mime,f.digest FROM ab.vehicle_files f WHERE f.scan_status='pending' AND NOT EXISTS(SELECT 1 FROM ab.vehicle_file_reviews r WHERE r.file_id=f.id) ORDER BY f.created_at LIMIT 20 $$;
CREATE FUNCTION ab.record_vehicle_scan(target uuid,result text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ab AS $$ DECLARE org uuid; BEGIN IF result NOT IN('clean','rejected') THEN RAISE EXCEPTION 'invalid verdict';END IF; SELECT tenant_id INTO org FROM ab.vehicle_files WHERE id=target AND scan_status='pending';IF org IS NOT NULL THEN INSERT INTO ab.vehicle_file_reviews VALUES(gen_random_uuid(),org,target,result,now()) ON CONFLICT(tenant_id,file_id)DO NOTHING;INSERT INTO ab.audit_events(id,tenant_id,actor_id,actor_type,action,entity_type,entity_id,fields,request_id)VALUES(gen_random_uuid(),org,'00000000-0000-4000-8000-000000000001','service','scanned','vehicle_file',target,ARRAY['scan_status',result],gen_random_uuid());END IF;END $$;
CREATE FUNCTION ab.enabled_vehicle_jobs() RETURNS TABLE(tenant_id uuid,company_id uuid) LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,ab AS $$ SELECT tenant_id,company_id FROM ab.vehicle_billing_jobs WHERE enabled $$;
REVOKE ALL ON FUNCTION ab.vehicle_immutable(),ab.vehicle_allocation_valid(),ab.vehicle_credit_valid(),ab.pending_vehicle_files(),ab.record_vehicle_scan(uuid,text),ab.enabled_vehicle_jobs() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ab.pending_vehicle_files(),ab.record_vehicle_scan(uuid,text) TO ab_scanner;
GRANT EXECUTE ON FUNCTION ab.enabled_vehicle_jobs() TO ab_runtime;
CREATE TABLE ab.vehicle_letter_templates(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,company_id uuid NOT NULL,version integer NOT NULL,payload_cipher text NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,company_id,version),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.vehicle_letters(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,company_id uuid NOT NULL,vehicle_id uuid NOT NULL,action_id uuid NOT NULL,template_id uuid NOT NULL,file_id uuid NOT NULL,letter_number bigint NOT NULL,approved_by uuid NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,action_id,template_id),UNIQUE(tenant_id,letter_number),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,vehicle_id)REFERENCES ab.vehicles(tenant_id,id),FOREIGN KEY(tenant_id,action_id)REFERENCES ab.vehicle_actions(tenant_id,id),FOREIGN KEY(tenant_id,template_id)REFERENCES ab.vehicle_letter_templates(tenant_id,id),FOREIGN KEY(tenant_id,file_id)REFERENCES ab.vehicle_files(tenant_id,id),FOREIGN KEY(tenant_id,approved_by)REFERENCES ab.users(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.vehicle_expense_payments(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,company_id uuid NOT NULL,expense_id uuid NOT NULL,operation_id uuid,amount numeric(21,3) NOT NULL CHECK(amount>0),payload_cipher text NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,expense_id),UNIQUE(tenant_id,operation_id),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,expense_id)REFERENCES ab.vehicle_expenses(tenant_id,id),FOREIGN KEY(tenant_id,operation_id)REFERENCES ab.finance_operations(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
DO $$ DECLARE tab text;BEGIN FOREACH tab IN ARRAY ARRAY['vehicle_letter_templates','vehicle_letters','vehicle_expense_payments'] LOOP EXECUTE format('ALTER TABLE ab.%I ENABLE ROW LEVEL SECURITY',tab);EXECUTE format('CREATE POLICY tenant_scope ON ab.%I USING(tenant_id=ab.tenant()) WITH CHECK(tenant_id=ab.tenant())',tab);EXECUTE format('GRANT SELECT,INSERT ON ab.%I TO ab_runtime',tab);EXECUTE format('CREATE TRIGGER history_immutable BEFORE UPDATE OR DELETE ON ab.%I FOR EACH ROW EXECUTE FUNCTION ab.vehicle_immutable()',tab);END LOOP;END $$;
CREATE TABLE ab.vehicle_imports(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,company_id uuid NOT NULL,actor_id uuid NOT NULL,source_hash text NOT NULL,payload_cipher text NOT NULL,cursor integer NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'Preview' CHECK(status IN('Preview','Running','Completed')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,actor_id,source_hash),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,actor_id)REFERENCES ab.users(tenant_id,id));
ALTER TABLE ab.vehicle_imports ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_scope ON ab.vehicle_imports USING(tenant_id=ab.tenant())WITH CHECK(tenant_id=ab.tenant());
GRANT SELECT,INSERT,UPDATE ON ab.vehicle_imports TO ab_runtime;
